-- Dumping structure for procedure iot.generate_random_numbers
DELIMITER //
CREATE PROCEDURE `generate_random_numbers`()
BEGIN
    DECLARE counter INT DEFAULT 0;

    WHILE counter < 10 DO
        SELECT
		    NOW() - (RAND() * 60) as timestamp,
		    floor(RAND() * 1000) + 1 as sensor_id,
		    RAND() * 100 as value,
		    'Location ' || floor(RAND() * 3) + 1 as location,
		    floor(RAND() * 3) + 1 as device_id,
		    floor(RAND() * 3) + 1 as sensor_type_id;
        SET counter = counter + 1;
    END WHILE;
END//
DELIMITER ;

